    button { padding: .7rem 1rem; border: 0; border-radius: 5px; background: #245bd5; color: white; font: inherit; cursor: pointer; }
    button:hover { background: #1748b5; }
    .project-row { justify-content: space-between; margin: .6rem 0; padding: .9rem 1rem; background: white; border: 1px solid #dce2ea; border-radius: 6px; }
