  </style>
</head>
<body>
<main id="app"></main>
<script type="module">
const app = document.querySelector('#app');
const escapeHtml = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));

async function render() {
  const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
  if (match) {
    const projects = await (await fetch('/api/projects')).json();
    const project = projects.find(item => item.id === Number(match[1]));
    if (project) {
      app.innerHTML = `<button type="button" id="back">Projects</button><h1>${escapeHtml(project.name)}</h1>`;
      app.querySelector('#back').addEventListener('click', () => { history.pushState({}, '', '/'); render(); });
      return;
    }
  }
  const projects = await (await fetch('/api/projects')).json();
  app.innerHTML = `<h1>Workboard</h1>
    <form id="create-form"><label for="project-name">Project name</label><input id="project-name" name="name" type="text"><button type="submit">Create project</button></form>
    <div class="alert" role="alert" aria-live="polite"></div>
    <section aria-label="Projects">${projects.map(project => `<div class="project-row" data-testid="project-row"><span>${escapeHtml(project.name)}</span><button type="button" data-project-id="${project.id}">Open project</button></div>`).join('')}</section>`;
  app.querySelector('#create-form').addEventListener('submit', async event => {
    event.preventDefault();
    const input = app.querySelector('#project-name');
    const name = input.value.trim();
    const alert = app.querySelector('.alert');
    if (!name) { alert.textContent = 'Project name is required'; return; }
    const response = await fetch('/api/projects', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name }) });
    if (!response.ok) { alert.textContent = 'Unable to create project'; return; }
    render();
  });
  app.querySelectorAll('[data-project-id]').forEach(button => button.addEventListener('click', () => {
    history.pushState({}, '', `/projects/${button.dataset.projectId}`); render();
  }));
}
window.addEventListener('popstate', render);
render();
</script>
</body>
</html>
